import {packetDetailsHTML,packetCompactHTML} from './packet-fields.js';
import {installFollowCamera} from './follow-camera.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fingerprint=s=>JSON.stringify({nodes:s.nodes.map(({id,type,name,parent,interfaces,services,rules,members,clusterId})=>({id,type,name,parent,interfaces,services,rules,members,clusterId})),links:s.links.map(({id,a,b,medium,length,kind})=>({id,a,b,medium,length,kind}))});
export class TrafficPlayer{
 constructor(canvas,getState){this.canvas=canvas;this.getState=getState;this.cursor=0;this.speed=1;this.frame=null;this.elapsed=0;const $=id=>document.getElementById(id);this.$=$;installFollowCamera(canvas);this.follow=true;try{this.follow=localStorage.getItem('infra-lab-follow-packet')!=='false'}catch{}this.syncFollow();$('trace-follow').onclick=()=>{this.follow=!this.follow;try{localStorage.setItem('infra-lab-follow-packet',String(this.follow))}catch{}this.syncFollow();if(this.follow&&this.result)this.canvas.followTraffic(this.result.trace[this.cursor]);else this.canvas.cancelCamera()};
  this.showPacketDetails=true;try{this.showPacketDetails=localStorage.getItem('infra-lab-packet-fields')!=='false'}catch{}this.syncPacketDetails();$('packet-fields').onclick=()=>{this.showPacketDetails=!this.showPacketDetails;try{localStorage.setItem('infra-lab-packet-fields',String(this.showPacketDetails))}catch{}this.syncPacketDetails();if(this.canvas.trafficView){this.canvas.trafficView.showPacketDetails=this.showPacketDetails;this.canvas.applyTraffic()}};
  $('trace-play').onclick=()=>this.playing?this.pause():this.play();$('trace-prev').onclick=()=>this.seek(this.cursor-1);$('trace-next').onclick=()=>this.seek(this.cursor+1);$('trace-replay').onclick=()=>{this.seek(0);this.play()};$('trace-finish').onclick=()=>this.seek(this.result.trace.length-1);$('trace-focus').onclick=()=>this.canvas.focusTraffic();$('trace-speed').onchange=e=>this.speed=Number(e.target.value);$('trace-seek').oninput=e=>this.seek(Number(e.target.value));$('trace-clear').onclick=()=>this.clear();
  $('result').addEventListener('click',e=>{const step=e.target.closest('[data-trace-step]');if(step)this.seek(Number(step.dataset.traceStep))});
 }
 start(result,request){this.clear(false);this.result=result;this.request=request;this.snapshot=fingerprint(this.getState());this.cursor=0;this.elapsed=0;this.$('trace-controls').hidden=false;this.$('demo-guide').open=false;this.$('trace-seek').max=Math.max(0,result.trace.length-1);
  this.$('result').innerHTML=`<div id="trace-outcome" class="resulthead">Проверка по шагам</div><div id="trace-stop-detail" class="trace-stop-detail" hidden></div>${result.ok&&request.protocol==='tcp'?`<div id="trace-http" class="http-preview" hidden><div class="browserbar">Учебный браузер клиента · ${esc(request.target)}:${esc(request.port)}</div><h3>Сайт из контейнера работает</h3><p>Nginx · HTTP 200</p><small>Запрос и ответ прошли модель сети.</small></div>`:''}<div class="trace-log">${result.trace.map((e,i)=>`<button class="trace-step ${e.type==='stop'?'trace-error-step':''}" data-trace-step="${i}"><small>${esc(e.stage||'Сеть')}</small><span>${i+1}. ${esc(e.label)}</span><span class="packet-step-summary">${packetCompactHTML(e)}</span></button>`).join('')}</div>`;
  this.paint(0);this.play();
 }
 clear(message=true){this.pause();this.canvas.cancelCamera();this.result=null;this.$('trace-controls').hidden=true;this.canvas.setTraffic(null);if(message)this.$('result').innerHTML='<div class="hint">Подсветка сброшена. Отправьте пакет для новой проверки.</div>'}
 syncPacketDetails(){this.$('packet-fields').setAttribute('aria-pressed',String(this.showPacketDetails));this.$('packet-fields').textContent='IP/порты: '+(this.showPacketDetails?'вкл':'выкл');this.$('packet-details').hidden=!this.showPacketDetails;this.$('result').classList.toggle('packet-fields-hidden',!this.showPacketDetails)}
 syncFollow(){this.$('trace-follow').setAttribute('aria-pressed',String(this.follow));this.$('trace-follow').textContent='Слежение: '+(this.follow?'вкл':'выкл')}
 invalidate(state){if(this.result&&fingerprint(state)!==this.snapshot)this.clear();}
 pause(){this.playing=false;if(this.frame!==null)cancelAnimationFrame(this.frame);this.frame=null;this.$('trace-play').textContent='▶ Продолжить'}
 play(){if(!this.result)return;if(this.result.trace.length<=1){this.paint(1);return}if(this.cursor>=this.result.trace.length-1){this.cursor=0;this.elapsed=0;this.paint(0)}this.playing=true;this.$('trace-play').textContent='Ⅱ Пауза';this.lastTime=performance.now();const tick=time=>{if(!this.playing)return;this.elapsed+=(time-this.lastTime)*this.speed;this.lastTime=time;const duration=700;if(this.elapsed>=duration){this.elapsed=0;this.cursor++;this.paint(0);if(this.cursor>=this.result.trace.length-1){this.pause();this.paint(1);return}}this.canvas.animateTraffic(Math.min(1,this.elapsed/duration));this.frame=requestAnimationFrame(tick)};this.frame=requestAnimationFrame(tick)}
 seek(i){if(!this.result)return;this.pause();this.cursor=Math.max(0,Math.min(this.result.trace.length-1,i));this.elapsed=0;this.paint(1)}
 paint(progress){const trace=this.result.trace,e=trace[this.cursor],done=this.cursor===trace.length-1;this.$('trace-stage').textContent=e.stage||'Сеть';this.$('trace-label').textContent=e.label;this.$('trace-counter').textContent=`${this.cursor+1} / ${trace.length}`;this.$('trace-seek').value=this.cursor;
  this.$('trace-controls').classList.toggle('trace-has-error',e.type==='stop');this.$('trace-outcome').textContent=done?(this.result.ok?'✓ Пакет доставлен и ответ получен':'× Пакет остановлен'):'Прохождение пакета…';this.$('trace-outcome').classList.toggle('fail',done&&!this.result.ok);
  const detail=this.$('trace-stop-detail');detail.hidden=e.type!=='stop';if(e.type==='stop'){const n=this.getState().nodes.find(n=>n.id===e.nodeId);detail.textContent=(n?'Остановка: '+n.name+'\n':'')+e.label}
  const http=this.$('trace-http');if(http)http.hidden=!done||!this.result.ok;
  this.$('result').querySelectorAll('[data-trace-step]').forEach(el=>{const i=Number(el.dataset.traceStep);el.classList.toggle('trace-current-step',i===this.cursor);el.classList.toggle('trace-past-step',i<this.cursor)});
  this.$('trace-play').disabled=trace.length<=1;if(done)this.$('trace-play').textContent='▶ Повторить';this.$('trace-prev').disabled=this.cursor===0;this.$('trace-next').disabled=done;this.$('trace-finish').disabled=done;
  this.$('packet-details').innerHTML=packetDetailsHTML(e);this.syncPacketDetails();
  this.canvas.setTraffic({showPacketDetails:this.showPacketDetails,event:e,visited:trace.slice(0,this.cursor+1),progress});if(this.follow)this.canvas.followTraffic(e);
  if(done&&this.scrolledOutcome!==this.cursor){const result=this.$('result'),pane=result.closest('.right');if(pane)pane.scrollTop+=result.getBoundingClientRect().top-pane.getBoundingClientRect().top-64;this.scrolledOutcome=this.cursor}else if(!done)this.scrolledOutcome=-1;
 }
}
